<div class="sl-head"><div><h1 class="sl-title">Logs</h1><p class="sl-lede">Search the application, message, PHP, cron and API logs of this installation</p></div><div class="row g8 wrap"><div class="dv-tabs"><?php foreach ((array) sl_get($d, 'tabs', []) as $t): ?><a class="<?= sl_v($t, 'cls') ?>" href="<?= sl_v($t, 'href') ?>"><?= sl_v($t, 'label') ?></a><?php endforeach; ?></div><a class="chipbtn" href="<?= sl_v($d, 'liveUrl') ?>"><i class="ic ic-sm i-activity" aria-hidden="true"></i>Live tail</a></div></div>
<section class="sl-card col g12"><form class="row wrap g12" method="get"><input type="hidden" name="tab" value="<?= sl_v($d, 'tab') ?>"><input type="hidden" name="level" value="<?= sl_v($d, 'level') ?>"><div class="sl-search"><i class="ic ic-sm i-search" aria-hidden="true"></i><input name="q" aria-label="Search logs" placeholder="Search text" value="<?= sl_v($d, 'q') ?>"></div><?php if ($d['tab'] === 'all'): ?><select class="sl-sel native" name="source" aria-label="Service" style="width:160px" onchange="this.form.submit()"><?php foreach ($d['sources'] as $k => $l): ?><option value="<?= h($k) ?>"<?= $d['source'] === $k ? ' selected' : '' ?>><?= h($l) ?></option><?php endforeach; ?></select><?php endif; ?><div class="sl-seg boxed"><?php foreach ((array) sl_get($d, 'levels', []) as $l): ?><a class="<?= sl_v($l, 'cls') ?>" href="<?= sl_v($l, 'href') ?>"><?= sl_v($l, 'label') ?></a><?php endforeach; ?></div><select class="sl-sel native" name="window" aria-label="Time window" style="width:140px" onchange="this.form.submit()"><?php foreach ($d['windows'] as $k => $l): ?><option value="<?= (int) $k ?>"<?= (int) $d['window'] === (int) $k ? ' selected' : '' ?>><?= h($l) ?></option><?php endforeach; ?></select><button class="sl-btn ghost sm" type="submit">Search</button></form>
<div class="row between mut sm"><span><?= h(sl_num(count($d['rows']))) ?> events shown · <?= (int) $d['nWarn'] ?> warnings · <?= (int) $d['nErr'] ?> errors</span><span>Newest first</span></div><div class="row g6" style="align-items:flex-end;height:90px" aria-hidden="true"><?php foreach ($d['hist'] as $hh): ?><div class="grow" style="height:<?= (int) $hh ?>%;background:var(--sky);border-radius:4px 4px 0 0"></div><?php endforeach; ?></div></section>
<?php if ($d['tab'] === 'php' && empty($d['phpPath'])): ?><div class="sl-banner" role="note"><i class="ic i-info" aria-hidden="true"></i><span>No PHP error log is configured. Set <span class="mono">CDP_ERROR_LOG</span> in config/config.php (see config.example.php).</span></div><?php endif; ?>
<?php if ($d['tab'] === 'cron' && empty($d['cronReady'])): ?><div class="sl-banner" role="note"><i class="ic i-info" aria-hidden="true"></i><span>The cron ledger needs <span class="mono">migrations/2026_11_06_freight_devops.sql</span>; cron scripts record runs by including helpers/cron_run.php.</span></div><?php endif; ?>
<?php if ($d['tab'] === 'api' && empty($d['apiTable'])): ?><div class="sl-banner" role="note"><i class="ic i-info" aria-hidden="true"></i><span>This installation has no <span class="mono">cdb_api_request_log</span> table, so API requests are not recorded yet. API errors still appear under All sources.</span></div><?php endif; ?>
<div class="split"><section class="a sl-card col g12"><h2 class="sl-ct">Events</h2><div class="term"><?php foreach ((array) sl_get($d, 'rows', []) as $i => $r): ?><a class="ln" href="<?= h(sl_url(['row' => $i])) ?>"><span class="ts"><?= sl_v($r, 'time') ?></span><span class="sv"><?= sl_v($r, 'sv') ?></span><span class="lv <?= sl_v($r, 'lc') ?>"><?= sl_v($r, 'lv') ?></span><span><?= sl_v($r, 'm') ?></span></a><?php endforeach; ?><?php if (!sl_get($d, 'rows')): ?><div class="ln"><span>No events match.</span></div><?php endif; ?></div></section>
<aside class="b col g16"><section class="sl-card col g12"><h2 class="sl-ct">Event</h2><?php if ($sel): ?><div class="mut sm"><?= sl_v($sel, 'time') ?> · <?= sl_v($sel, 'sv') ?> · <?= sl_v($sel, 'lv') ?></div><div class="code" style="white-space:pre-wrap"><?= sl_v($sel, 'm') ?><?= $sel['json'] ? "\n\n" . h($sel['json']) : '' ?></div><div class="row g8"><button class="sl-btn ghost sm" data-sl-copy="<?= sl_v($sel, 'm') ?>"><i class="ic ic-sm i-file" aria-hidden="true"></i>Copy</button><a class="sl-btn ghost sm" href="<?= h(sl_route('DevIssues', ['new' => 1, 'title' => mb_substr($sel['m'], 0, 120), 'log' => $sel['m'], 'page' => $sel['sv']])) ?>">Open ticket</a><a class="sl-btn sm" href="<?= sl_route('DevAlerts') ?>">Create alert</a></div><?php else: ?><span class="mut sm">Pick an event.</span><?php endif; ?></section>
<section class="sl-card col g8"><h2 class="sl-ct">Saved views · 24 h</h2><?php foreach ((array) sl_get($d, 'saved', []) as $sv): ?><a class="dv-row" href="<?= h($sv['href']) ?>"><span class="grow"><?= h($sv['t']) ?></span><span class="sl-badge"><?= (int) $sv['n'] ?></span></a><?php endforeach; ?></section></aside></div>
